package brasfoot;
import java.nio.file.*;import java.util.*;import javax.swing.*;import java.awt.*;import javax.imageio.ImageIO;
public final class NativePenaltyResultWindowTest{
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);GameAdapter game=Fixture.create(root.resolve("game/Brasfoot22-23/teams/abcrn_bra.ban").toFile(),root.resolve("game/Brasfoot22-23/teams/corinthians_bra.ban").toFile());best.I match=game.currentMatches().get(0);Data.set(match,"fB",1);Data.set(match,"fC",1);match.i(new int[]{5,4});match.u(match.hc());match.a(false);MatchPlayback playback=new MatchPlayback(game.currentMatches());Map<String,Object> scheduled=Data.map(Data.list(playback.snapshot().get("matches")).get(0));check(scheduled.get("homePenalties")==null&&scheduled.get("winnerClubId")==null&&!Boolean.TRUE.equals(scheduled.get("penaltiesAvailable")),"Unplayed fixture exposed a decision");check("x".equals(Data.map(Data.list(CareerViews.clubAgenda(match.hc().lk()).get("fixtures")).get(0)).get("result")),"Scheduled agenda result must use native x placeholder");match.a(true);Map<String,Object> finalPlayback=playback.snapshot();finalPlayback.put("status","FINISHED");Map<String,Object> row=Data.map(Data.list(finalPlayback.get("matches")).get(0));check(Boolean.TRUE.equals(row.get("penaltiesAvailable"))&&Data.number(row.get("homePenalties"))==5&&Data.number(row.get("winnerClubId"))==match.hc().lk(),"Final decision not transported by identity");Map<String,Object> agenda=Data.map(Data.list(CareerViews.clubAgenda(match.hc().lk()).get("fixtures")).get(0));check("1 (5) x 1 (4)".equals(agenda.get("result")),"Agenda omitted penalty scores");match.i(new int[]{-1,-1});match.u(null);Map<String,Object> state=new LinkedHashMap<String,Object>();state.put("playback",finalPlayback);JFrame[] frame={null};SwingUtilities.invokeAndWait(()->{JFrame owner=new JFrame("Resultado de penaltis do host");frame[0]=owner;NativeMatchPanel panel=new NativeMatchPanel(owner,game.currentMatches());panel.muted(true);owner.add(panel);owner.pack();owner.setLocationRelativeTo(null);owner.setVisible(true);panel.project(state);check(match.hQ()[0]==5&&match.hQ()[1]==4&&match.hR()==match.hc(),"Native projection lost shootout or winner");check(match.hu()==1&&match.hw()==1,"Shootout was added to regular goals");check(((JLabel)Data.get(panel,"Hn")).getText().contains("5 x 4"),"Featured score omitted shootout");row.put("penaltiesAvailable",false);row.put("homePenalties",null);row.put("awayPenalties",null);row.put("winnerClubId",null);panel.project(state);check(match.hQ()[0]==-1&&match.hQ()[1]==-1&&match.hR()==null&&!((JLabel)Data.get(panel,"Hn")).getText().contains("5 x 4"),"Unavailable update retained a stale shootout decision");row.put("penaltiesAvailable",true);row.put("homePenalties",5);row.put("awayPenalties",4);row.put("winnerClubId",match.hc().lk());panel.project(state);});new Robot().waitForIdle();Thread.sleep(350);try{Path folder=root.resolve("build/evidence-penalty-result");Files.createDirectories(folder);ImageIO.write(new Robot().createScreenCapture(frame[0].getBounds()),"png",folder.resolve("result.png").toFile());}finally{SwingUtilities.invokeAndWait(()->frame[0].dispose());}match.i(new int[]{-1,-1});match.u(null);Map<String,Object> normal=Data.map(Data.list(playback.snapshot().get("matches")).get(0));check(normal.get("homePenalties")==null&&!Boolean.TRUE.equals(normal.get("penaltiesAvailable")),"No-shootout match was treated as 0 x 0 shootout");System.out.println("PASS finalized host penalty decision reaches native I, winner and featured score; agenda preserves normal goals; unavailable results remain null");
 }
}
